<?php
require_once "inc/layout.php";
require_once "../config.php";
adminHeader("Actualización Página 451 - Arte Rupestre");
$pdo = getDB();

// 1. Asegurar LONGTEXT en content
try {
    $pdo->exec("ALTER TABLE pages MODIFY COLUMN content LONGTEXT");
} catch (Exception $e) {
    // Si ya es LONGTEXT o falla, continuar
}

$content = base64_decode("");

// 2. Actualizar página 451
$stmt = $pdo->prepare("UPDATE pages SET content = ? WHERE id = 451");
$stmt->execute([$content]);

echo "<div class=\"card\" style=\"max-width: 800px; margin: 2rem auto; padding: 2rem; background: #fff; border-radius: 8px; box-shadow: 0 4px 15px rgba(0,0,0,0.05);\">";
echo "<h2 style=\"color: #2e7d32; margin-top: 0;\"><i class=\"fas fa-check-circle\"></i> ¡Página 451 Actualizada con Éxito!</h2>";
echo "<p style=\"font-size: 1.1rem;\">La columna <code>content</code> se ha ampliado a <strong>LONGTEXT</strong> y se ha guardado el 100% del código HTML de <strong>Arte Rupestre</strong> sin ningún recorte.</p>";
echo "<div style=\"display: flex; gap: 1rem; margin-top: 1.5rem;\">";
echo "<a href=\"../page.php?id=451\" target=\"_blank\" class=\"btn btn-primary\" style=\"background: #2e7d32;\"><i class=\"fas fa-external-link-alt\"></i> Ver Página en la Web</a>";
echo "<a href=\"pages.php?action=edit&id=451\" class=\"btn\" style=\"background: #e2e8f0;\"><i class=\"fas fa-edit\"></i> Editar en Admin</a>";
echo "</div>";
echo "</div>";

adminFooter();
